/* ============================================================
   PATCH 1.0.14 — 409 removed_assignees_have_logs: диалог выбора
   Перехват window.fetch, как в PATCH 19 (duplicate_name) и PATCH 27 (task_has_logs).
   ============================================================ */
(function(){
'use strict';
if (window.__trkRemovedAssigneesFetchV1014) return;
window.__trkRemovedAssigneesFetchV1014 = true;

var _native = window.fetch;
if (typeof _native !== 'function') return;

function _esc(s){
    return String(s == null ? '' : s).replace(/[&<>"']/g, function(c){
        return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
    });
}

function _showDialog(data, originalBody){
    return new Promise(function(resolve){
        var existing = document.getElementById('trkRemovedAssigneesModal');
        if (existing) existing.remove();

        var m = document.createElement('div');
        m.id = 'trkRemovedAssigneesModal';
        m.className = 'modal trk-removed-assignees-modal';
        m.style.setProperty('z-index', '9000', 'important');

        var rows = (data.removed || []).map(function(r){
            var per = '';
            if (r.first_date && r.last_date) {
                per = r.first_date === r.last_date ? r.first_date : (r.first_date + ' — ' + r.last_date);
            }
            return '<div class="trk-ra-row">'
                +   '<span class="trk-ra-name">' + _esc(r.name) + '</span>'
                +   '<span class="trk-ra-meta">' + (r.logs_count || 0) + ' отм. · ' + _esc(per) + '</span>'
                + '</div>';
        }).join('');

        m.innerHTML = ''
            + '<div class="modal-content">'
            + '  <h2>⚠ Удаление сотрудников из задачи</h2>'
            + '  <p class="trk-ra-sub">Следующие сотрудники будут удалены из задачи, но у них есть отметки:</p>'
            + '  <div class="trk-ra-list">' + rows + '</div>'
            + '  <p class="trk-ra-q">Что сделать с их отметками?</p>'
            + '  <div class="modal-actions trk-ra-actions">'
            + '    <button type="button" class="btn btn-danger" data-ra="delete">🗑 Удалить отметки</button>'
            + '    <button type="button" class="btn btn-secondary" data-ra="keep">💾 Оставить отметки</button>'
            + '    <button type="button" class="btn btn-secondary" data-ra="cancel">Отмена</button>'
            + '  </div>'
            + '</div>';

        document.body.appendChild(m);
        m.classList.add('active');

        var resolved = false;
        function finish(choice){
            if (resolved) return;
            resolved = true;
            m.classList.remove('active');
            m.removeEventListener('click', onClick);
            resolve(choice);
        }
        function onClick(e){
            if (e.target === m) return;
            var btn = e.target.closest && e.target.closest('[data-ra]');
            if (!btn) return;
            finish(btn.getAttribute('data-ra'));
        }
        m.addEventListener('click', onClick);
    });
}

window.fetch = function(url, opts){
    var isSave = (typeof url === 'string' && url.indexOf('/api/tracker/task/save') !== -1);
    var isPost = opts && (opts.method || 'GET').toUpperCase() === 'POST';
    if (!isSave || !isPost) return _native.apply(this, arguments);

    var body = {};
    try { body = JSON.parse(opts.body || '{}'); } catch(e){}
    // Повторный запрос от самого перехвата — не трогаем.
    if (body.removed_logs_action) return _native.apply(this, arguments);

    var self = this;
    return _native.apply(this, arguments).then(function(r){
        if (r.status !== 409) return r;
        return r.clone().json().then(function(d){
            if (!d || d.error !== 'removed_assignees_have_logs') return r;
            return _showDialog(d, body).then(function(choice){
                if (choice === 'cancel') {
                    return new Response(JSON.stringify({success: false, error: 'cancelled'}), {
                        status: 200, headers: {'Content-Type': 'application/json'}
                    });
                }
                var newBody = Object.assign({}, body, {removed_logs_action: choice});
                var newOpts = Object.assign({}, opts, {body: JSON.stringify(newBody)});
                return _native.call(self, url, newOpts);
            });
        });
    });
};

})();

